# >>> STATIC
_static_options_web_sharing() {
    cat <<-'ARGCEOF'
	on	new sessions will allow web sharing through the local web server if it is online
	off	new sessions will not allow web sharing unless they explicitly opt-in to it
	disabled	new sessions will not allow web sharing and will not be able to opt-in to it
ARGCEOF
}

_static_action_switch_mode_input_mode() {
    cat <<-'ARGCEOF'
	normal	In Normal mode, input is always written to the terminal, except for the shortcuts leading to other modes
	locked	In Locked mode, input is always written to the terminal and all shortcuts are disabled except the one leading back to normal mode
	resize	Resize mode allows resizing the different existing panes
	pane	Pane mode allows creating and closing panes, as well as moving between them
	tab	Tab mode allows creating and closing tabs, as well as moving between them
	scroll	Scroll mode allows scrolling up and down within a pane
	enter-search	EnterSearch mode allows for typing in the needle for a search in the scroll buffer of a pane
	search	Search mode allows for searching a term in a pane (superset of Scroll)
	rename-tab	RenameTab mode allows assigning a new name to a tab
	rename-pane	RenamePane mode allows assigning a new name to a pane
	session	Session mode allows detaching sessions
	move	Move mode allows moving the different existing panes within a tab
	prompt	Prompt mode allows interacting with active prompts
	tmux	Tmux mode allows for basic tmux keybindings functionality
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_direction() {
    printf '%s\n' right down left up
}

_choice_shell() {
    local shell
    local -a shells=()
    if [[ -f /etc/shells ]]; then
        while IFS= read -r shell; do
            [[ -z $shell || $shell == '#'* ]] && continue
            shells+=("${shell##*/}")
        done </etc/shells
    fi
    if ((${#shells[@]} == 0)); then
        shells=(bash zsh fish sh)
    fi
    printf '%s\n' "${shells[@]}" | gawk '!seen[$0]++'
}

_choice_zellij_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_zellij_command_args() {
    local index="${argc__dash:-0}"
    if ((${#argc__positionals[@]} <= index + 1)); then
        _choice_zellij_command
    else
        _argc_util_comp_subcommand "$index"
    fi
}

_choice_zellij_layout() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path exts=.kdl
        return 0
    fi
    printf '%s\n' default compact classic strider
    _helper_zellij_layout_file
    return 0
}

_choice_zellij_pane_id() {
    zellij action list-panes 2>/dev/null | gawk 'NR > 1 && NF { print $1 }'
}

_choice_zellij_plugin() {
    zellij list-aliases 2>/dev/null
}

_choice_zellij_session() {
    zellij list-sessions -ns 2>/dev/null
}

_choice_zellij_tab_id() {
    zellij action list-tabs 2>/dev/null | gawk 'NR > 1 && NF { print $1 }'
}

_choice_zellij_tab_name() {
    zellij action list-tabs 2>/dev/null | gawk -F'  +' 'NR > 1 && NF >= 3 { print $3 }'
}

_helper_zellij_layout_file() {
    local dir file
    for dir in \
        "${ZELLIJ_LAYOUT_DIR:-}" \
        "$(_argc_util_path_resolve CONFIG_DIR zellij/layouts)" \
        "/etc/zellij/layouts"; do
        [[ -n $dir && -d $dir ]] || continue
        for file in "$dir"/*.kdl; do
            if [[ -f $file ]]; then
                basename "$file" .kdl
            fi
        done
    done
    return 0
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
